@extends('layouts.app') @php($label=$type==='income'?'Pemasukan':'Pengeluaran') @section('title',($transaction?'Edit ':'Tambah ').$label) @section('content')
<div class="page-head"><div><h1>{{ $transaction?'Edit':'Tambah' }} {{ $label }}</h1><p>Lengkapi transaksi dan minimal satu detail.</p></div></div><form class="card transaction-form" method="post" action="{{ $transaction?route($type.'s.update',$transaction):route($type.'s.store') }}">@csrf @if($transaction) @method('put') @endif<div class="form-grid"><label>Tanggal<input type="date" name="date" value="{{ old('date',$transaction?->date?->format('Y-m-d') ?? today()->format('Y-m-d')) }}" required></label><label>Kategori<select name="category_id" required><option value="">Pilih kategori</option>@foreach($categories as $c)<option value="{{ $c->id }}" @selected(old('category_id',$transaction?->category_id)==$c->id)>{{ $c->name }}</option>@endforeach</select></label><label class="wide">Keterangan<textarea name="description" rows="2">{{ old('description',$transaction?->description) }}</textarea></label></div><div class="detail-head"><h2>Detail {{ $label }}</h2><button type="button" class="btn soft" onclick="addDetail()">+ Tambah detail</button></div><div id="details">@php($details=old('details',$transaction?->details?->toArray() ?? [['name'=>'','amount'=>'','note'=>'']])) @foreach($details as $i=>$detail)<div class="detail-row"><label>Nama<input name="details[{{ $i }}][name]" value="{{ $detail['name'] }}" required></label><label>Nominal<input class="amount" type="number" min="1" name="details[{{ $i }}][amount]" value="{{ $detail['amount'] }}" required oninput="total()"></label><label>Catatan<input name="details[{{ $i }}][note]" value="{{ $detail['note']??'' }}"></label><button type="button" class="remove" onclick="removeDetail(this)">×</button></div>@endforeach</div><div class="form-total"><small>TOTAL</small><strong id="total">Rp0</strong></div><div class="actions"><a class="btn soft" href="{{ route($type.'s.index') }}">Batal</a><button class="btn primary">Simpan {{ $label }}</button></div></form>
@push('scripts')<script>let detailIndex={{ count($details) }};function addDetail(){let d=document.createElement('div');d.className='detail-row';d.innerHTML=`<label>Nama<input name="details[${detailIndex}][name]" required></label><label>Nominal<input class="amount" type="number" min="1" name="details[${detailIndex}][amount]" required oninput="total()"></label><label>Catatan<input name="details[${detailIndex}][note]"></label><button type="button" class="remove" onclick="removeDetail(this)">×</button>`;document.querySelector('#details').append(d);detailIndex++}function removeDetail(b){if(document.querySelectorAll('.detail-row').length>1){b.parentElement.remove();total()}}function total(){let n=[...document.querySelectorAll('.amount')].reduce((s,e)=>s+(parseInt(e.value)||0),0);document.querySelector('#total').textContent='Rp'+new Intl.NumberFormat('id-ID').format(n)}total()</script>@endpush
